insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P1_INTU', 'accuracy', '더하기 1은 ''바로 다음 수''예요', '수를 셀 때 1, 2, 3, 4… 하고 하나씩 커지지요?
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P1_INTU', 'speed', '다음 수를 바로 떠올려요', '다 맞혔어요! 이제 손가락으로 세지 않고 다음 수를 바로 말하는 연습을 해요.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P1_COMM', 'accuracy', '1 + 5도 5 + 1과 같아요', '더하기는 순서를 바꿔도 답이 같아요. 이것을 ''교환법칙''이라고 해요.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P1_COMM', 'speed', '큰 수부터 시작하면 빨라져요', '1이 앞에 있어도 큰 수에서 출발하면 한 칸만 가면 돼요.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P2_INTRO', 'accuracy', '더하기 2는 두 칸 간 수예요', '수직선에서 오른쪽으로 두 번 뛰면 더하기 2예요.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P2_INTRO', 'speed', '두 칸을 한 번에 뛰어요', '다 맞혔어요! 이제 한 칸씩 세지 말고 두 칸을 한 번에 건너뛰어 봐요.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P2_INTU', 'accuracy', '두 칸 간 수를 떠올려요', '더하기 2는 두 칸 간 수. 2→→4, 3→→5.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P2_INTU', 'speed', '''하나 건너뛰기''를 눈으로 해요', '정확하게 잘 풀었어요. 수를 보면 다음 수를 건너뛰고 그 다음 수를 바로 말해요.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P2_COMM', 'accuracy', '2 + 4는 4 + 2와 같아요', '더하기는 순서를 바꿔도 같아요. 3 + 2 = 2 + 3.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P2_COMM', 'speed', '큰 수에서 두 칸', '정답은 모두 맞았어요! 2가 앞에 나와도 바로 큰 수로 출발하는 습관을 들여요.', '''2 더하기''가 보이면 뒤의 수에서 두 칸!') on conflict do nothing;
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P3_INTRO', 'accuracy', '더하기 3은 세 칸 간 수예요', '수직선에서 오른쪽으로 세 번 뛰면 더하기 3.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P3_INTRO', 'speed', '세 칸을 덩어리로 봐요', '다 맞혔어요! 이제 세 칸을 한 번에 보는 연습을 해요.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P3_INTU', 'accuracy', '세 칸 간 수를 떠올려요', '더하기 3은 세 칸 간 수. 2→→→5, 3→→→6.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P3_INTU', 'speed', '도착하는 수를 바로 말해요', '정답은 모두 맞았어요. 세는 소리를 점점 작게, 마지막 수만 크게 말해 보세요.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P3_COMM', 'accuracy', '3 + 4는 4 + 3과 같아요', '순서를 바꿔도 더한 값은 같아요. 4 + 3 = 3 + 4.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P3_COMM', 'speed', '큰 수에서 세 칸', '다 맞혔어요! 작은 수가 앞에 나와도 큰 수에서 출발하는 것을 한 번에 해 봐요.', '''3 더하기''가 보이면 뒤의 수에서 세 칸!') on conflict do nothing;
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P4_INTRO', 'accuracy', '더하기 4는 네 칸 간 수예요', '수직선에서 오른쪽으로 네 번 뛰면 더하기 4.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P4_INTRO', 'speed', '두 칸 + 두 칸', '정답은 모두 맞았어요! 네 칸을 하나씩 세면 느려요.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P4_INTU', 'accuracy', '네 칸 간 수를 떠올려요', '더하기 4는 네 칸 간 수. 2→→→→6, 3→→→→7.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P4_INTU', 'speed', '+2를 두 번으로 빠르게', '다 맞혔어요! 5 + 4는 5 → 7 → 9. 두 번만 뛰면 돼요.', '+4는 두 번 뛰기!') on conflict do nothing;
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P4_COMM', 'accuracy', '4 + 3은 3 + 4와 같아요', '순서를 바꿔도 같아요. 4가 앞에 있어도, 4가 뒤에 있어도 더한 값은 똑같아요.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P4_COMM', 'speed', '큰 수에서 출발', '정답은 모두 맞았어요! 둘 중 큰 수를 먼저 찾고, 작은 수만큼 가는 순서를 몸에 익혀요.', '''어느 쪽이 커?''를 먼저 보는 습관!') on conflict do nothing;
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P5_INTRO', 'accuracy', '더하기 5는 다섯 칸 간 수예요', '수직선에서 오른쪽으로 다섯 번 뛰면 더하기 5.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P5_INTRO', 'speed', '''한 손''을 통째로 더해요', '다 맞혔어요! 5는 한 손이니까 하나씩 세지 않아도 돼요.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P5_INTU', 'accuracy', '다섯 칸 간 수를 떠올려요', '더하기 5는 다섯 칸 간 수.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P5_INTU', 'speed', '5 묶음으로 보기', '정답은 모두 맞았어요! 4 + 5는 ''4와 한 손'', 9. 묶음으로 보면 바로 보여요.', '5 묶음 생각하기!') on conflict do nothing;
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P5_COMM', 'accuracy', '5 + 2는 2 + 5와 같아요', '순서를 바꿔도 같아요. 2 + 5 = 5 + 2.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_P5_COMM', 'speed', '5에서 출발', '다 맞혔어요! 5가 보이면 5에서 출발해 나머지 수만큼만 가요.', '5는 출발점!') on conflict do nothing;
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_COMP10', 'accuracy', '더해서 10이 되는 짝', '10칸짜리 상자를 생각해요. 9칸이 차 있으면 빈 칸은 1칸이에요.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('ADD_COMP10', 'speed', '10의 짝을 외워요', '다 맞혔어요! 10의 짝(9와 1, 8과 2, 7과 3, 6과 4, 5와 5)을 노래처럼 외우면 바로 떠올라요.', '손가락 열 개 중 접힌 것과 펴진 것이 10의 짝이에요.') on conflict do nothing;
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('TIMES_2', 'accuracy', '2단은 2씩 묶음이에요', '2 × 3은 ''2씩 3묶음''이라는 뜻이에요. 2을 세 번 더한 것과 같아요: 2 + 2 + 2 = 6.
