insert into skill_explanations (skill_id, weakness, title, body, tip) values ('TIMES_MIX_A', 'accuracy', '몇 단인지 먼저 봐요', '섞여 나오면 헷갈리기 쉬워요. 먼저 앞의 수를 보고 ''몇 단''인지 정해요.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('TIMES_MIX_A', 'speed', '섞여도 바로바로', '다 맞혔어요! 섞인 문제도 단을 정하는 시간을 줄이면 빨라져요.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('TIMES_MIX_B', 'accuracy', '큰 단은 아는 단으로 바꿔요', '6·7·8·9단은 어려워요. 순서를 바꾸면 아는 단이 될 때가 많아요.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('TIMES_MIX_B', 'speed', '어려운 짝을 집중해서', '다 맞혔어요! 6×7, 7×8, 8×6처럼 자주 헷갈리는 짝을 따로 외우면 빨라져요.
insert into skill_explanations (skill_id, weakness, title, body, tip) values ('TAP_L1', 'accuracy', '순서대로 차근차근', '다음에 누를 숫자를 먼저 입으로 말하고, 화면에서 찾아서 눌러요.
